import"./chunk-VC46IEJQ.js";var e=(o,t)=>({en:o,zh:t}),a=(o,t,r,n,h,i,l,d,s)=>({name:o,desc:t,tour:r,...s?{spoiler:s}:{},source:{confidence:n,refs:h,book:i,unknown:l,interpretation:d}}),c={id:"pyke",intro:e("Pyke, seat of House Greyjoy, was built on a headland that the sea has since broken into islands and stacks. Its keeps now stand on separate rocks, tied together by bridges of stone and rope high above the surf.","\u6D3E\u514B\u57CE\u662F\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u539F\u5EFA\u4E8E\u4E00\u5904\u6D77\u5CAC\u4E4B\u4E0A\uFF0C\u540E\u6765\u6D77\u6C34\u5C06\u5CAC\u89D2\u5543\u6210\u4E86\u96F6\u6563\u7684\u5C9B\u7901\u4E0E\u77F3\u67F1\u3002\u5982\u4ECA\u5404\u5EA7\u5821\u697C\u5206\u7ACB\u4E8E\u4E0D\u540C\u7684\u5CA9\u67F1\uFF0C\u51ED\u77F3\u6865\u4E0E\u7EF3\u6865\u76F8\u8FDE\uFF0C\u9AD8\u60AC\u4E8E\u6D6A\u6D9B\u4E4B\u4E0A\u3002"),notes:e("From the novels (A Clash of Kings especially): a castle broken across sea-stacks and joined by bridges; a curtain wall and gatehouse on the mainland bluff; the Great Keep, Kitchen Keep and Bloody Keep on their own rocks; the old Sea Tower on the outermost pillar. Ships use nearby Lordsport. Invented here: the arrangement, sizes, bridge forms, the cove and all surrounding features.","\u5C0F\u8BF4\uFF08\u5C24\u5176\u662F\u300A\u5217\u738B\u7684\u7EB7\u4E89\u300B\uFF09\u786E\u7ACB\uFF1A\u57CE\u5821\u6563\u5E03\u4E8E\u82E5\u5E72\u6D77\u8680\u77F3\u67F1\u4E4B\u4E0A\uFF0C\u4EE5\u6865\u76F8\u8FDE\uFF1B\u9646\u4E0A\u5D16\u9876\u6709\u5E55\u5899\u4E0E\u95E8\u697C\uFF1B\u4E3B\u5821\u3001\u53A8\u623F\u5821\u4E0E\u8840\u5821\u5404\u636E\u4E00\u5CA9\uFF1B\u53E4\u8001\u7684\u6D77\u5854\u7ACB\u4E8E\u6700\u5916\u4FA7\u7684\u77F3\u67F1\u4E0A\u3002\u8239\u53EA\u505C\u9760\u9644\u8FD1\u7684\u9886\u4E3B\u6E2F\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u6574\u4F53\u5E03\u5C40\u3001\u5C3A\u5BF8\u3001\u6865\u7684\u6837\u5F0F\u3001\u6D77\u6E7E\u53CA\u4E00\u5207\u5468\u8FB9\u666F\u7269\u3002"),tour:["gatehouse-and-wall","stone-bridges","great-keep","great-hall","bloody-keep","kitchen-keep","sea-tower","sea-stacks","longship-cove"],sources:[{ref:"acok",checked:"memory",note:e("Theon's return to Pyke describes the broken headland, the curtain wall and gatehouse, the bridges and the named keeps. Recalled; not re-read.","\u5E2D\u6069\u91CD\u8FD4\u6D3E\u514B\u57CE\u7684\u7AE0\u8282\u63CF\u5199\u4E86\u65AD\u88C2\u7684\u6D77\u5CAC\u3001\u5E55\u5899\u4E0E\u95E8\u697C\u3001\u6865\u6881\u53CA\u5404\u5EA7\u6709\u540D\u7684\u5821\u697C\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002")},{ref:"affc",checked:"memory",note:e("The rope bridge to the Sea Tower recurs in the Iron Islands chapters. Recalled.","\u901A\u5F80\u6D77\u5854\u7684\u7EF3\u6865\u5728\u94C1\u7FA4\u5C9B\u8BF8\u7AE0\u4E2D\u518D\u6B21\u51FA\u73B0\u3002\u51ED\u8BB0\u5FC6\u3002")},{ref:"awoiaf",checked:"search-snippet",note:e("Search summaries of the wiki and concordance confirm the stack-and-bridge layout, the crescent wall from cliff to cliff and the lack of a safe anchorage (ships use Lordsport). Pages not fetched.","\u7EF4\u57FA\u4E0E\u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\u4E86\u77F3\u67F1\u52A0\u6865\u6881\u7684\u5E03\u5C40\u3001\u5D16\u95F4\u65B0\u6708\u5F62\u57CE\u5899\uFF0C\u4EE5\u53CA\u57CE\u4E0B\u6CA1\u6709\u5B89\u5168\u951A\u5730\uFF08\u8239\u53EA\u505C\u9760\u9886\u4E3B\u6E2F\uFF09\u3002\u9875\u9762\u672A\u6293\u53D6\u3002")},{ref:"twoiaf",checked:"memory",note:e("The Iron Islands' history and the Greyjoys' rule from Pyke. Recalled.","\u94C1\u7FA4\u5C9B\u7684\u5386\u53F2\u53CA\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF\u5750\u9547\u6D3E\u514B\u57CE\u7684\u7EDF\u6CBB\u3002\u51ED\u8BB0\u5FC6\u3002")}],landmarks:{"great-keep":a(e("Great Keep","\u4E3B\u5821"),e("The largest keep, on the biggest rock beyond the gatehouse, holding the castle's main hall.","\u6700\u5927\u7684\u5821\u697C\uFF0C\u7ACB\u4E8E\u95E8\u697C\u5916\u6700\u5927\u7684\u4E00\u5757\u5CA9\u77F3\u4E0A\uFF0C\u57CE\u5821\u7684\u5927\u5385\u5C31\u5728\u5176\u4E2D\u3002"),e("The Great Keep holds the biggest rock: cold stone, smoky hall.","\u4E3B\u5821\u5360\u636E\u6700\u5927\u7684\u5CA9\u77F3\uFF1A\u77F3\u58C1\u51B0\u51B7\uFF0C\u5927\u5385\u70DF\u718F\u3002"),"high",["acok","awoiaf"],e("A Great Keep stands on the largest of Pyke's rocks and is joined to the others by bridges.","\u4E3B\u5821\u7ACB\u4E8E\u6D3E\u514B\u57CE\u6700\u5927\u7684\u5CA9\u77F3\u4E0A\uFF0C\u4EE5\u6865\u4E0E\u5176\u4F59\u5404\u5904\u76F8\u8FDE\u3002"),e("Its interior, size and shape.","\u5185\u90E8\u3001\u89C4\u6A21\u4E0E\u5916\u5F62\u3002"),e("A squat square keep with corner towers and a taller upper tower.","\u77EE\u58EE\u7684\u65B9\u5F62\u4E3B\u5821\uFF0C\u56DB\u89D2\u8BBE\u5854\uFF0C\u9876\u4E0A\u518D\u52A0\u4E00\u5C42\u9AD8\u5854\u3002")),"great-hall":a(e("The Great Hall","\u5927\u5385"),e("A long, smoky hall where the Seastone Chair, carved from oily black stone, stands on a dais.","\u4E00\u5EA7\u70DF\u718F\u706B\u71CE\u7684\u957F\u5385\uFF0C\u4EE5\u6CB9\u4EAE\u9ED1\u77F3\u96D5\u6210\u7684\u6D77\u77F3\u4E4B\u4F4D\u7ACB\u4E8E\u9AD8\u53F0\u4E0A\u3002"),e("At the end of this smoky hall stands the Seastone Chair of the Greyjoys.","\u70DF\u718F\u957F\u5385\u7684\u5C3D\u5934\uFF0C\u4FBF\u662F\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF\u7684\u6D77\u77F3\u4E4B\u4F4D\u3002"),"medium",["acok","awoiaf"],e("Pyke has a hall with the Seastone Chair, a seat carved like a kraken from oily black stone.","\u6D3E\u514B\u57CE\u6709\u4E00\u5EA7\u8BBE\u6D77\u77F3\u4E4B\u4F4D\u7684\u5927\u5385\uFF1B\u90A3\u5F20\u5EA7\u6905\u7531\u6CB9\u4EAE\u9ED1\u77F3\u96D5\u6210\u6D77\u602A\u4E4B\u5F62\u3002"),e("Which keep holds the hall, its size and decoration.","\u5927\u5385\u4F4D\u4E8E\u54EA\u5EA7\u5821\u697C\uFF0C\u53CA\u5176\u89C4\u6A21\u4E0E\u88C5\u9970\u3002"),e("Shown as a low gabled wing of the Great Keep; the interior is not modelled.","\u8868\u73B0\u4E3A\u4E3B\u5821\u65C1\u7684\u4F4E\u77EE\u5C71\u5899\u4FA7\u7FFC\uFF1B\u5185\u90E8\u672A\u5EFA\u6A21\u3002")),"sea-tower":a(e("Sea Tower","\u6D77\u5854"),e("The oldest tower, tall and round, on the outermost pillar; the lord's solar is here.","\u6700\u53E4\u8001\u7684\u5854\uFF0C\u9AD8\u5927\u6D51\u5706\uFF0C\u7ACB\u4E8E\u6700\u5916\u4FA7\u7684\u77F3\u67F1\u4E0A\uFF1B\u9886\u4E3B\u4E66\u623F\u5373\u5728\u6B64\u3002"),e("The oldest tower stands alone on the last pillar, reached by a swaying bridge.","\u6700\u53E4\u8001\u7684\u5854\u5B64\u7ACB\u4E8E\u6700\u5916\u4FA7\u7684\u77F3\u67F1\u4E0A\uFF0C\u987B\u7ECF\u4E00\u9053\u6447\u6643\u7684\u6865\u624D\u80FD\u62B5\u8FBE\u3002"),"high",["acok","affc","awoiaf"],e("The Sea Tower is Pyke's oldest tower, on the outermost stack, where Balon Greyjoy keeps his solar; it is reached by a rope bridge.","\u6D77\u5854\u662F\u6D3E\u514B\u57CE\u6700\u53E4\u8001\u7684\u5854\uFF0C\u4F4D\u4E8E\u6700\u5916\u4FA7\u7684\u77F3\u67F1\uFF0C\u5DF4\u9686\xB7\u845B\u96F7\u4E54\u4F0A\u7684\u4E66\u623F\u5C31\u8BBE\u5728\u8FD9\u91CC\uFF1B\u9700\u7ECF\u7EF3\u6865\u62B5\u8FBE\u3002"),e("Height, number of floors, and how many bridges lead to it.","\u9AD8\u5EA6\u3001\u5C42\u6570\uFF0C\u4EE5\u53CA\u901A\u5F80\u6B64\u5854\u7684\u6865\u6709\u51E0\u9053\u3002"),e("A single drum tower topped by a smaller drum.","\u4E00\u5EA7\u5706\u9F13\u5F62\u5854\uFF0C\u9876\u4E0A\u518D\u53E0\u4E00\u5C42\u8F83\u5C0F\u7684\u5706\u5854\u3002")),"bloody-keep":a(e("Bloody Keep","\u8840\u5821"),e("A grim keep on its own rock where guests are lodged; it takes its name from an ancient massacre.","\u72EC\u636E\u4E00\u5CA9\u7684\u9634\u68EE\u5821\u697C\uFF0C\u7528\u6765\u5B89\u7F6E\u5BBE\u5BA2\uFF1B\u5176\u540D\u6E90\u4E8E\u4E00\u6869\u53E4\u8001\u7684\u5C60\u6740\u3002"),e("Named for an old slaughter of guests, the Bloody Keep still lodges visitors.","\u56E0\u53E4\u65F6\u5BBE\u5BA2\u906D\u5C60\u800C\u5F97\u540D\uFF0C\u8840\u5821\u81F3\u4ECA\u4ECD\u7528\u6765\u63A5\u5F85\u6765\u5BA2\u3002"),"medium",["acok","awoiaf"],e("Theon is lodged in the Bloody Keep, named for a long-ago massacre of a river king's sons there.","\u5E2D\u6069\u88AB\u5B89\u7F6E\u5728\u8840\u5821\uFF1B\u6B64\u5821\u5F97\u540D\u4E8E\u5F88\u4E45\u4EE5\u524D\u4E00\u4F4D\u6CB3\u6D41\u4E4B\u738B\u7684\u513F\u5B50\u4EEC\u5728\u6B64\u9047\u5BB3\u3002"),e("Its layout, and the precise details of the legend.","\u5E03\u5C40\uFF0C\u4EE5\u53CA\u4F20\u8BF4\u7684\u5177\u4F53\u7EC6\u8282\u3002"),e("A square keep with four turrets.","\u56DB\u89D2\u5E26\u5854\u697C\u7684\u65B9\u5F62\u5821\u3002")),"kitchen-keep":a(e("Kitchen Keep","\u53A8\u623F\u5821"),e("A service keep on a rock of its own, where the household's food is prepared.","\u72EC\u636E\u4E00\u5CA9\u7684\u6742\u52A1\u5821\u697C\uFF0C\u5168\u5E9C\u7684\u996D\u98DF\u5728\u6B64\u70F9\u5236\u3002"),e("Even the kitchens get their own rock at Pyke.","\u5728\u6D3E\u514B\u57CE\uFF0C\u8FDE\u53A8\u623F\u90FD\u72EC\u5360\u4E00\u5757\u5CA9\u77F3\u3002"),"medium",["acok","awoiaf"],e("A Kitchen Keep is named among Pyke's keeps.","\u53A8\u623F\u5821\u662F\u6D3E\u514B\u57CE\u6709\u540D\u53EF\u8003\u7684\u5821\u697C\u4E4B\u4E00\u3002"),e("Its size, position and form.","\u89C4\u6A21\u3001\u4F4D\u7F6E\u4E0E\u5F62\u5236\u3002"),e("A gabled hall with chimneys and a small tower.","\u5E26\u70DF\u56F1\u4E0E\u5C0F\u5854\u7684\u5C71\u5899\u5385\u3002")),"stone-bridges":a(e("Bridges","\u6865\u6881"),e("Bridges cross the gaps between the rocks: arched stone near the shore, rope and planks farther out.","\u6865\u6881\u6A2A\u8DE8\u5CA9\u67F1\u95F4\u7684\u7A7A\u9699\uFF1A\u8FD1\u5CB8\u4E3A\u77F3\u62F1\u6865\uFF0C\u8D8A\u5F80\u5916\u8D8A\u662F\u7EF3\u7D22\u4E0E\u6728\u677F\u3002"),e("The bridges grow narrower and wilder the farther out you go.","\u8D8A\u5F80\u5916\uFF0C\u6865\u8D8A\u7A84\uFF0C\u4E5F\u8D8A\u9669\u3002"),"high",["acok","affc","awoiaf"],e("Bridges of stone and of rope join the keeps across the chasms.","\u77F3\u6865\u4E0E\u7EF3\u6865\u8DE8\u8D8A\u6DF1\u6E0A\uFF0C\u5C06\u5404\u5EA7\u5821\u697C\u8FDE\u5728\u4E00\u8D77\u3002"),e("Number, length and exact form of the spans.","\u6865\u7684\u6570\u91CF\u3001\u957F\u5EA6\u4E0E\u786E\u5207\u5F62\u5236\u3002"),e("Seven spans, the outermost of rope and planks.","\u5171\u4E03\u9053\u6865\uFF0C\u6700\u5916\u4E00\u9053\u4E3A\u7EF3\u7D22\u4E0E\u6728\u677F\u3002"),e("Balon Greyjoy dies in a fall from the bridge to the Sea Tower during a storm.","\u5DF4\u9686\xB7\u845B\u96F7\u4E54\u4F0A\u5728\u4E00\u573A\u98CE\u66B4\u4E2D\uFF0C\u4ECE\u901A\u5F80\u6D77\u5854\u7684\u6865\u4E0A\u5760\u4EA1\u3002")),"gatehouse-and-wall":a(e("Gatehouse and Wall","\u95E8\u697C\u4E0E\u57CE\u5899"),e("On the mainland bluff a curtain wall runs from cliff to cliff, with a gatehouse at its centre and towers on either side.","\u9646\u4E0A\u5D16\u9876\uFF0C\u4E00\u9053\u5E55\u5899\u81EA\u4E00\u4FA7\u60AC\u5D16\u5EF6\u4F38\u81F3\u53E6\u4E00\u4FA7\uFF0C\u95E8\u697C\u5C45\u4E2D\uFF0C\u4E24\u65C1\u8BBE\u5854\u3002"),e("Only this wall and gatehouse stand on the mainland; the rest is out on the rocks.","\u53EA\u6709\u8FD9\u9053\u57CE\u5899\u4E0E\u95E8\u697C\u7559\u5728\u9646\u5730\u4E0A\uFF0C\u5176\u4F59\u90FD\u5728\u6D77\u4E2D\u5CA9\u67F1\u4E4B\u4E0A\u3002"),"medium",["acok","awoiaf"],e("A curtain wall with a central gatehouse and square towers closes off the bluff on the landward side.","\u5E55\u5899\u4ECE\u9646\u4FA7\u5C01\u4F4F\u5D16\u9876\uFF0C\u4E2D\u95F4\u662F\u95E8\u697C\uFF0C\u4E24\u65C1\u6709\u65B9\u5854\u3002"),e("The wall's height and the number of towers.","\u57CE\u5899\u9AD8\u5EA6\u4E0E\u5854\u697C\u6570\u91CF\u3002"),e("Five towers on a shallow arc.","\u6D45\u5F27\u5F62\u57CE\u5899\u4E0A\u8BBE\u4E94\u5EA7\u5854\u697C\u3002")),"sea-stacks":a(e("Sea Stacks","\u6D77\u8680\u77F3\u67F1"),e("Pillars of black rock rise from the sea, ringed by white water.","\u9ED1\u8272\u77F3\u67F1\u62D4\u6D77\u800C\u8D77\uFF0C\u5468\u8EAB\u767D\u6D6A\u7FFB\u6D8C\u3002"),e("Each stack is a fragment of the headland the sea has eaten away.","\u6BCF\u6839\u77F3\u67F1\uFF0C\u90FD\u662F\u88AB\u6D77\u6C34\u8680\u53BB\u7684\u6D77\u5CAC\u6B8B\u5757\u3002"),"high",["acok","awoiaf"],e("The castle was built on a headland that the sea later broke into islands and stacks.","\u57CE\u5821\u539F\u5EFA\u4E8E\u6D77\u5CAC\u4E4B\u4E0A\uFF0C\u540E\u6765\u6D77\u6C34\u5C06\u5CAC\u89D2\u51B2\u6210\u5C9B\u7901\u4E0E\u77F3\u67F1\u3002"),e("How many stacks there are and their shapes.","\u77F3\u67F1\u7684\u6570\u91CF\u4E0E\u5F62\u72B6\u3002"),e("Thirteen pillars drawn, most of them empty.","\u7ED8\u51FA\u5341\u4E09\u6839\u77F3\u67F1\uFF0C\u5927\u591A\u65E0\u4EBA\u5C45\u4F4F\u3002")),"longship-cove":a(e("Longship Cove","\u957F\u8239\u6E7E"),e("A rocky cove below the cliffs where black-hulled longships are drawn up; Pyke itself has no safe harbour.","\u5D16\u4E0B\u7684\u5CA9\u77F3\u5C0F\u6E7E\uFF0C\u9ED1\u8272\u957F\u8239\u62D6\u4E0A\u5CB8\u8FB9\uFF1B\u6D3E\u514B\u57CE\u672C\u8EAB\u5E76\u65E0\u5B89\u5168\u6E2F\u6E7E\u3002"),e("Pyke has no safe anchorage; ships put in at Lordsport nearby.","\u6D3E\u514B\u57CE\u6CA1\u6709\u5B89\u5168\u951A\u5730\uFF0C\u8239\u53EA\u90FD\u505C\u9760\u9644\u8FD1\u7684\u9886\u4E3B\u6E2F\u3002"),"low",["acok","awoiaf"],e("Visitors land at Lordsport and ride to the castle; no harbour at Pyke itself is described.","\u6765\u5BA2\u5728\u9886\u4E3B\u6E2F\u767B\u5CB8\uFF0C\u518D\u9A91\u9A6C\u524D\u5F80\u57CE\u5821\uFF1B\u4E66\u4E2D\u672A\u5199\u6D3E\u514B\u57CE\u672C\u8EAB\u6709\u6E2F\u53E3\u3002"),e("Whether any cove lies beside the castle.","\u57CE\u5821\u65C1\u662F\u5426\u771F\u6709\u5C0F\u6E7E\u3002"),e("A small cove with two beached longships is invented.","\u505C\u7740\u4E24\u8258\u957F\u8239\u7684\u5C0F\u6E7E\u4E3A\u865A\u6784\u3002"))}};export{c as default};
